ruleToc.nextTocUrl:
@js:
var all_url = [];
var next_url;
if(n=result.match(/pagestats.+?\d+\/(\d+).*?</)) {
  n=result.match(/pagestats.+?(\d+)\/(\d+).*?</);
  var cur = n[1]
  var max = n[2]
  java.log(n)
  java.log(cur)
  java.log(max)
  while (cur < max) {
    cur = parseInt(cur) + 1
    next_url = baseUrl.replace(/\/(\d+)\/(\d+)_\d+\//, "/$1/$2/")
    next_url = baseUrl.replace(/\/(\d+)\/(\d+)\//, "/$1/$2_" + cur + "/")
    java.log(next_url)
    all_url.push(next_url)
  }
}
all_url

